head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > summaryAuto]<br/>GridView 의 Body Table 에 summary 속성을 자동 생성할지 설정합니다.",
    "validation" : [
        "GridView 의 Body Table 에 summary 속성을 자동 생성할지 설정합니다. 하위 버전 호환을 위한 속성이며 향후 제거(Deprecated)될 예정입니다.",
        "true 로 설정하면 Header 값을 조합하여 summary 속성을 자동 생성합니다.",
        "false (default) 로 설정하면 summary 속성을 자동 생성하지 않습니다.",
        "summary 속성은 HTML5 에서 폐기(Deprecated)된 속성이므로, 문서 타입이 HTML5 인 환경에서는 적용되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // 조건 읽기
    //  - con_summaryAuto : 미설정('') / true / false. 이번 샘플의 주 대상 (Property 미설정 케이스 포함). gdl_boolean -> getText()
    let summaryAutoVal = con_summaryAuto.getText();

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // Property 설정은 createCList 공통 함수 사용 (빈 문자열 value 는 자동 제외 → 미설정 처리)
    let properties = {
        summaryAuto: summaryAutoVal,
        dataList: "data:dlt_bind",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblSummaryAuto = (summaryAutoVal === '') ? '미설정' : summaryAutoVal;
    $c.gcm.createLabel('label="summaryAuto=' + lblSummaryAuto + ' 로 GridView 생성 (Header 4컬럼 + gBody). summaryAuto=true 시 Header 값(사번,이름,부서,직급)을 조합하여 Body Table summary 속성을 자동 생성하나, 현재 페이지는 HTML5 문서 타입이라 적용되지 않습니다."', '', 'label1');

    // target 생성 (summaryAuto 조건부)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="summaryAuto 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="사번"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="이름"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="부서"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="직급"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Body Table 엘리먼트의 summary 속성값을 DOM 으로 읽어 반환 (속성 미부여 시 null)
scwin.getBodySummaryAttr = function () {
    let bodyTable = document.querySelector("table[id*='target1_body_table']");
    if (!bodyTable) {
        return undefined;
    }
    // getAttribute 는 속성 자체가 없으면 null 반환
    return bodyTable.getAttribute("summary");
}



// Body Table summary 속성 / summaryAuto 옵션값 확인 (@description / @propval / @spec)
//  - summaryAuto=true 시 Header 값을 조합한 자동값이 부여되어야 하나, HTML5 문서 타입에서는 적용되지 않아 미부여로 출력됨
scwin.btn_checkSummary_onclick = function () {
    let summaryAttr = scwin.getBodySummaryAttr();
    wf_body_bottom.getObj("scwin").setReturnValue("Body Table summary 속성 : " + (summaryAttr === null ? '미부여(HTML5 폐기 - 미적용)' : "'" + summaryAttr + "'"));
    wf_body_bottom.getObj("scwin").setReturnValue("summaryAuto 옵션값 : " + target1.options.summaryAuto);
}
